-- Trigram GIN indexes: fast fuzzy matching of free-text VLM food names against ~7.8k entries
-- (NutritionLookupService.findByFoodKeySimilar / findByDisplayNameSimilar use pg_trgm similarity).
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX IF NOT EXISTS idx_food_nutrition_name_trgm ON food_nutrition USING gin (display_name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_food_nutrition_key_trgm  ON food_nutrition USING gin (food_key gin_trgm_ops);
